begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users (id) values ('dddddddd-1111-4111-8111-111111111111'), ('dddddddd-2222-4222-8222-222222222222');
insert into public.roleplay_materials (id, user_id, title, situation, speaker_one_name, speaker_two_name) values ('aaaaaaaa-1111-4111-8111-111111111111', 'dddddddd-1111-4111-8111-111111111111', 'Original', 'Situation', 'Partner', 'Learner');
insert into public.roleplay_lines (material_id,user_id,line_order,speaker_order,text,translation) values ('aaaaaaaa-1111-4111-8111-111111111111','dddddddd-1111-4111-8111-111111111111',0,2,'Hello.','안녕하세요.');
set local role authenticated;
select set_config('request.jwt.claim.sub','dddddddd-2222-4222-8222-222222222222',true);
select throws_ok($q$select public.update_roleplay_material('aaaaaaaa-1111-4111-8111-111111111111', '{"title":"Edited","situation":"Updated","tags":[],"lines":[{"order":0,"speakerOrder":2,"text":"Hello."}]}'::jsonb)$q$, 'P0001', 'Material unavailable', 'roleplay: other owner rejected');
select set_config('request.jwt.claim.sub','dddddddd-1111-4111-8111-111111111111',true);
select lives_ok($q$select public.update_roleplay_material('aaaaaaaa-1111-4111-8111-111111111111', '{"title":"Edited","situation":"Updated","tags":[],"lines":[{"order":0,"speakerOrder":2,"text":"Hello."}]}'::jsonb)$q$, 'roleplay: valid edit');
select is((select title from public.roleplay_materials where id='aaaaaaaa-1111-4111-8111-111111111111'), 'Edited', 'roleplay: same parent updated');
select is((select translation from public.roleplay_lines where material_id='aaaaaaaa-1111-4111-8111-111111111111'), '안녕하세요.', 'roleplay: unchanged text retains translation');
select throws_ok($q$select public.update_roleplay_material('aaaaaaaa-1111-4111-8111-111111111111', '{"title":"Broken","situation":"Updated","tags":[],"lines":[{"order":0,"speakerOrder":2,"text":""}]}'::jsonb)$q$, '23514', null, 'roleplay: invalid child rejected');
select is((select title from public.roleplay_materials where id='aaaaaaaa-1111-4111-8111-111111111111'), 'Edited', 'roleplay: parent rolled back');
select is((select text from public.roleplay_lines where material_id='aaaaaaaa-1111-4111-8111-111111111111'), 'Hello.', 'roleplay: child rollback');
update public.roleplay_materials set status='deleted', deleted_at=now() where id='aaaaaaaa-1111-4111-8111-111111111111';
select throws_ok($q$select public.update_roleplay_material('aaaaaaaa-1111-4111-8111-111111111111', '{"title":"Edited","situation":"Updated","tags":[],"lines":[{"order":0,"speakerOrder":2,"text":"Hello."}]}'::jsonb)$q$, 'P0001', 'Material unavailable', 'roleplay: deleted material cannot edit');
reset role;
insert into public.memorization_materials (id, user_id, title) values ('bbbbbbbb-1111-4111-8111-111111111111', 'dddddddd-1111-4111-8111-111111111111', 'Original');
insert into public.memorization_material_paragraphs(id,material_id,user_id,paragraph_order) values ('eeeeeeee-1111-4111-8111-111111111111','bbbbbbbb-1111-4111-8111-111111111111','dddddddd-1111-4111-8111-111111111111',0);
insert into public.memorization_material_sentences(paragraph_id,material_id,user_id,sentence_order,text,translation) values ('eeeeeeee-1111-4111-8111-111111111111','bbbbbbbb-1111-4111-8111-111111111111','dddddddd-1111-4111-8111-111111111111',0,'Hello.','안녕하세요.');
set local role authenticated;
select set_config('request.jwt.claim.sub','dddddddd-2222-4222-8222-222222222222',true);
select throws_ok($q$select public.update_memorization_material('bbbbbbbb-1111-4111-8111-111111111111', '{"title":"Edited","tags":[],"paragraphs":[{"order":0,"sentences":[{"order":0,"text":"Hello."}]}]}'::jsonb)$q$, 'P0001', 'Material unavailable', 'memorization: other owner rejected');
select set_config('request.jwt.claim.sub','dddddddd-1111-4111-8111-111111111111',true);
select lives_ok($q$select public.update_memorization_material('bbbbbbbb-1111-4111-8111-111111111111', '{"title":"Edited","tags":[],"paragraphs":[{"order":0,"sentences":[{"order":0,"text":"Hello."}]}]}'::jsonb)$q$, 'memorization: valid edit');
select is((select title from public.memorization_materials where id='bbbbbbbb-1111-4111-8111-111111111111'), 'Edited', 'memorization: same parent updated');
select is((select translation from public.memorization_material_sentences where material_id='bbbbbbbb-1111-4111-8111-111111111111'), '안녕하세요.', 'memorization: unchanged text retains translation');
select throws_ok($q$select public.update_memorization_material('bbbbbbbb-1111-4111-8111-111111111111', '{"title":"Broken","tags":[],"paragraphs":[{"order":0,"sentences":[{"order":0,"text":""}]}]}'::jsonb)$q$, '23514', null, 'memorization: invalid child rejected');
select is((select title from public.memorization_materials where id='bbbbbbbb-1111-4111-8111-111111111111'), 'Edited', 'memorization: parent rolled back');
select is((select text from public.memorization_material_sentences where material_id='bbbbbbbb-1111-4111-8111-111111111111'), 'Hello.', 'memorization: child rollback');
update public.memorization_materials set status='deleted', deleted_at=now() where id='bbbbbbbb-1111-4111-8111-111111111111';
select throws_ok($q$select public.update_memorization_material('bbbbbbbb-1111-4111-8111-111111111111', '{"title":"Edited","tags":[],"paragraphs":[{"order":0,"sentences":[{"order":0,"text":"Hello."}]}]}'::jsonb)$q$, 'P0001', 'Material unavailable', 'memorization: deleted material cannot edit');
reset role;
select * from finish();
rollback;
